import{lawsData,lawsTabs,lawsTimeline}from"./data.js";import{TabNav}from"./components/TabNav.js";import{LawCard,LawDetail}from"./components/LawCard.js";import{TimelineItem}from"./components/TimelineItem.js";document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("laws-app");let e="cover",t=null;function n(){return`<div class="laws-cover">\n      <h2>From the Regulating Act to the Bharatiya Nyaya Sanhita</h2>\n      <p>\n        India's legal system has evolved over 250 years — from early British\n        parliamentary oversight of the East India Company, through the\n        Indian Penal Code and the Constitution, to today's GST regime and\n        the newly enacted Bharatiya Nyaya Sanhita.\n      </p>\n      <div class="cover-stats">\n        <div class="cover-stat">\n          <span class="cover-stat-value">${lawsData.length}</span>\n          <span class="cover-stat-label">Laws covered</span>\n        </div>\n        <div class="cover-stat">\n          <span class="cover-stat-value">1773</span>\n          <span class="cover-stat-label">Earliest act</span>\n        </div>\n        <div class="cover-stat">\n          <span class="cover-stat-value">2023</span>\n          <span class="cover-stat-label">Latest reform</span>\n        </div>\n      </div>\n      <button class="cover-cta" id="explore-laws-btn">Explore the Laws <span class="arrow">→</span></button>\n    </div>`}function s(){switch(e){case"cover":default:return n();case"laws":return`<div class="laws-grid">${lawsData.map(a=>LawCard(a,t?.id===a.id)).join("")}</div>\n      <div class="law-detail-wrap">${t?LawDetail(t):'<p class="law-detail-placeholder">Select a law above to read more.</p>'}</div>`;case"timeline":return`<div class="laws-timeline">${lawsTimeline.map(a=>{const e=lawsData.find(e=>e.id===a.lawId);return TimelineItem(a,e)}).join("")}</div>`}}function l(){a.innerHTML=`\n      <div class="laws-page">\n        <div class="page-header">\n          <h1>History of Indian Laws</h1>\n          <p>From the Regulating Act of 1773 to the Bharatiya Nyaya Sanhita — how India's legal system has evolved</p>\n        </div>\n        ${TabNav(lawsTabs,e)}\n        <div class="laws-content" id="laws-content">\n          ${s()}\n        </div>\n      </div>`,function(){document.querySelectorAll(".laws-tab-btn").forEach(a=>{a.addEventListener("click",()=>{e=a.dataset.tab,l()})});const a=document.getElementById("explore-laws-btn");a&&a.addEventListener("click",()=>{e="laws",l()});document.querySelectorAll(".law-card-btn, .law-card").forEach(a=>{a.addEventListener("click",e=>{const n=a.dataset.id||e.currentTarget.dataset?.id;n&&(t=lawsData.find(a=>a.id===n)||t,l())})}),document.querySelectorAll(".timeline-item").forEach(a=>{a.addEventListener("click",()=>{const n=a.dataset.lawId;n&&(t=lawsData.find(a=>a.id===n)||t,e="laws",l())})})}()}l()});